CREATE FUNCTION protect_stripe_webhook_event_evidence()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
	IF TG_OP = 'DELETE' THEN
		RAISE EXCEPTION 'stripe_webhook_events evidence cannot be deleted';
	END IF;

	IF OLD.stripe_event_id IS DISTINCT FROM NEW.stripe_event_id
		OR OLD.event_type IS DISTINCT FROM NEW.event_type
		OR OLD.stripe_payment_intent_id IS DISTINCT FROM NEW.stripe_payment_intent_id
		OR OLD.raw_payload IS DISTINCT FROM NEW.raw_payload
		OR OLD.received_at IS DISTINCT FROM NEW.received_at THEN
		RAISE EXCEPTION 'stripe_webhook_events evidence cannot be changed';
	END IF;

	RETURN NEW;
END;
$$;
--> statement-breakpoint
CREATE TRIGGER stripe_webhook_events_protect_evidence
BEFORE UPDATE OR DELETE ON "stripe_webhook_events"
FOR EACH ROW
EXECUTE FUNCTION protect_stripe_webhook_event_evidence();
